SELECT 1

/* cppi::ae5c5485a38764ac14d9e11b61067669cd086414cd4b19d76353bc9ec4b67fc5 */
SELECT ss.security_name, ss.scd_id, ss.security_identifier, ss.origination_date, ss.start_date, ss.end_date, ss.amortization_method, ss.amortization_first_payment_date, ss.amortization_frequency, ss.amortization_percentage FROM reference.ci_sentry_security ss where ss.amortization_method = 'Customized Cashflows' and 
ss.scd_id in ('PD1001108', 'IMOFF', 'PD1001113')

/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

