/* cppi::b5a900ce61ebb8605174b6082850948b4b82ed5865cbff78408fd8fa17def65e */
SELECT COUNT(*) FROM (WITH filtered_index AS (SELECT business_date, id_cppib_index, index_description, rimes_source_code, rimes_source_description, index_value_base, return_daily_base, inception_return_base, feed_version FROM market.cppib_index WHERE id_cppib_index IN ('G0O1_TR_CAD_0_0', 'G0O1_TR_USD_0_0', '1662_TR_CAD_0_0', '1662_TR_USD_0_0') AND business_date = DATE '2025-04-30'), latest_feed_versions AS (SELECT id_cppib_index, business_date, MAX(feed_version) AS feed_version FROM filtered_index GROUP BY id_cppib_index, business_date) SELECT f.business_date, f.id_cppib_index, f.index_description, f.return_daily_base, f.inception_return_base FROM filtered_index f JOIN latest_feed_versions lfv ON f.id_cppib_index = lfv.id_cppib_index AND f.business_date = lfv.business_date AND f.feed_version = lfv.feed_version
